parameters.jsCode:
const input = $input.first().json;
const body = input.body ?? input;

const requiredFields = [
  "runId",
  "projectId",
  "message",
  "callbackUrl",
  "callbackToken",
];

for (const field of requiredFields) {
  if (
    typeof body[field] !== "string" ||
    body[field].trim() === ""
  ) {
    throw new Error(`Missing or invalid field: ${field}`);
  }
}

if (
  !Array.isArray(body.evidenceIds) ||
  !Array.isArray(body.evidence)
) {
  throw new Error("Invalid evidence payload");
}

for (const item of body.evidence) {
  if (
    typeof item.id !== "string" ||
    typeof item.url !== "string"
  ) {
    throw new Error("Invalid evidence item");
  }

  const isValidUrl = /^https?:\/\/[^/\s?#]+(?:[/?#]|$)/i.test(
    item.url.trim()
  );

  if (!isValidUrl) {
    throw new Error("Invalid evidence URL");
  }
}

const callbackUrlIsValid =
  /^https?:\/\/[^/\s?#]+(?:[/?#]|$)/i.test(body.callbackUrl.trim());

if (!callbackUrlIsValid) {
  throw new Error("Invalid callback URL");
}

return [
  {
json: {
  runId: body.runId,
  projectId: body.projectId,
  message: body.message,
  generationFormat:
    body.generationFormat === "PER_STEP" ? "PER_STEP" : "OVERALL",
  evidenceIds: body.evidenceIds,
  evidence: body.evidence,
  callbackUrl: body.callbackUrl,
  callbackToken: body.callbackToken,
},
  },
];

const input = $input.first().json;

if (!Array.isArray(input.evidence)) {
  throw new Error("Evidence must be an array");
}

// Keep one item even when no evidence was selected.
if (input.evidence.length === 0) {
  return [
    {
      json: {
        ...input,
        evidenceItem: null,
        hasEvidence: false,
      },
    },
  ];
}

// Create one workflow item for each evidence attachment.
return input.evidence.map((evidenceItem) => ({
  json: {
    ...input,
    evidenceItem,
    hasEvidence: true,
  },
}));

const items = $input.all();

if (items.length === 0) {
  return [];
}

const firstItem = items[0];
const binary = {};
const evidenceFiles = [];

items.forEach((item, index) => {
  const file = item.binary?.evidenceFile;

  if (!file) {
    throw new Error(
      `Evidence file missing for item ${index + 1}`
    );
  }

  const binaryKey = `evidence_${index + 1}`;

  binary[binaryKey] = file;

  evidenceFiles.push({
    id: item.json.evidenceItem.id,
    binaryProperty: binaryKey,
  });
});

return [
  {
    json: {
      ...firstItem.json,
      evidenceFiles,
      evidenceCount: evidenceFiles.length,
      hasEvidence: true,
    },
    binary,
  },
];

const item = $input.first();

if (!item) {
  throw new Error("No generation request received");
}

return [
  {
    json: {
      ...item.json,
      evidenceFiles: [],
      evidenceCount: 0,
      hasEvidence: false,
    },
  },
];

const item = $input.first();

if (!item) {
  throw new Error("No generation context received");
}

const evidenceFiles = item.json.evidenceFiles ?? [];

return [
  {
    json: {
      ...item.json,
      evidenceFiles,
      evidenceCount: evidenceFiles.length,
      hasEvidence: evidenceFiles.length > 0,
    },
    binary: item.binary ?? {},
  },
];

const item = $input.first();

if (!item) {
  throw new Error("No Ollama response received");
}

const context = $("Build Generation Context").first().json;
const rawText = item.json.message?.content;

if (typeof rawText !== "string" || !rawText.trim()) {
  throw new Error("Ollama response text is missing");
}

const cleanedText = rawText
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/, "")
  .trim();

// When the model stops mid-answer (output limit, or stuck repeating itself),
// the JSON is cut off. Recover every test case object that was completed
// before the break; the incomplete last one is dropped.
function salvageTestCases(text) {
  const key = text.indexOf('"testCases"');
  const start = key === -1 ? -1 : text.indexOf("[", key);
  if (start === -1) return [];

  const cases = [];
  let depth = 0;
  let inString = false;
  let escaped = false;
  let objectStart = -1;

  for (let i = start + 1; i < text.length; i += 1) {
    const ch = text[i];

    if (inString) {
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }

    if (ch === '"') {
      inString = true;
    } else if (ch === "{") {
      if (depth === 0) objectStart = i;
      depth += 1;
    } else if (ch === "}") {
      depth -= 1;
      if (depth === 0 && objectStart !== -1) {
        try {
          cases.push(JSON.parse(text.slice(objectStart, i + 1)));
        } catch {
          // Not valid on its own; leave it out.
        }
        objectStart = -1;
      }
    } else if (ch === "]" && depth === 0) {
      break;
    }
  }

  return cases;
}

let parsed;
let truncated = false;

try {
  parsed = JSON.parse(cleanedText);
} catch (error) {
  const salvaged = salvageTestCases(cleanedText);

  if (salvaged.length === 0) {
    throw new Error(
      `Ollama returned invalid JSON: ${error.message}. The response may have been truncated.`
    );
  }

  parsed = { testCases: salvaged };
  truncated = true;
}

if (
  !parsed ||
  typeof parsed !== "object" ||
  !Array.isArray(parsed.testCases) ||
  parsed.testCases.length === 0
) {
  throw new Error("Ollama response must contain at least one test case");
}

const generationFormat =
  context.generationFormat === "PER_STEP" ? "PER_STEP" : "OVERALL";

// Limits enforced by the AI QA Studio callback schema. A case over a limit
// would make the app reject the whole callback, so it is skipped here instead.
const MAX_CASES = 100;
const MAX_TITLE = 300;
const MAX_TEXT = 5000;
const MAX_STEPS = 50;

function toText(value) {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return JSON.stringify(value);
}

// Returns a normalized test case, or throws with the reason it can't be used.
function normalizeCase(original) {
  if (!original || typeof original !== "object" || Array.isArray(original)) {
    throw new Error("must be an object");
  }

  const title = typeof original.title === "string" ? original.title.trim() : "";
  if (!title) throw new Error("has an invalid title");
  if (title.length > MAX_TITLE) {
    throw new Error(`has a title longer than ${MAX_TITLE} characters`);
  }

  const text = {};
  for (const field of ["description", "precondition", "data"]) {
    text[field] = toText(original[field]);
    if (text[field].length > MAX_TEXT) {
      throw new Error(`has a ${field} longer than ${MAX_TEXT} characters`);
    }
  }

  const steps = original.steps;
  if (
    !Array.isArray(steps) ||
    steps.length === 0 ||
    steps.length > MAX_STEPS ||
    steps.some((step) => typeof step !== "string" || !step.trim())
  ) {
    throw new Error("has invalid steps");
  }

  const base = {
    title,
    description: text.description,
    precondition: text.precondition,
    steps,
    data: text.data,
  };

  if (generationFormat === "PER_STEP") {
    // Small models sometimes add an overall expectedResult as well. It is
    // not sent to the app for PER_STEP cases, so it is ignored.
    const results = original.stepExpectedResults;
    if (
      !Array.isArray(results) ||
      results.length !== steps.length ||
      results.some(
        (result) =>
          typeof result !== "string" ||
          !result.trim() ||
          result.trim().length > MAX_TEXT
      )
    ) {
      throw new Error("must have exactly one non-empty expected result per step");
    }

    return { ...base, stepExpectedResults: results.map((result) => result.trim()) };
  }

  const expectedResult =
    typeof original.expectedResult === "string" ? original.expectedResult.trim() : "";
  if (!expectedResult || expectedResult.length > MAX_TEXT) {
    throw new Error("has an invalid expected result");
  }

  return { ...base, expectedResult };
}

// Small models sometimes repeat the same test case over and over. Titles are
// compared ignoring case, spacing and punctuation; the first one is kept.
function titleKey(title) {
  return title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();
}

const normalizedTestCases = [];
const skipped = [];
const firstCaseByTitle = new Map();

if (truncated) {
  skipped.push("The response was cut off; the incomplete last test case was dropped");
}

for (const [index, original] of parsed.testCases.entries()) {
  const caseNumber = index + 1;

  if (normalizedTestCases.length >= MAX_CASES) {
    skipped.push(`Test case ${caseNumber}: over the limit of ${MAX_CASES} test cases`);
    continue;
  }

  try {
    const testCase = normalizeCase(original);
    const key = titleKey(testCase.title);

    if (firstCaseByTitle.has(key)) {
      skipped.push(`Test case ${caseNumber} duplicates test case ${firstCaseByTitle.get(key)}`);
      continue;
    }

    firstCaseByTitle.set(key, caseNumber);
    normalizedTestCases.push(testCase);
  } catch (error) {
    // Skip one malformed case instead of failing the whole batch; the user
    // reviews the remaining cases before anything is saved.
    skipped.push(`Test case ${caseNumber} ${error.message}`);
  }
}

if (normalizedTestCases.length === 0) {
  throw new Error(`Ollama returned no usable test cases. ${skipped.join("; ")}`);
}

return [
  {
    json: {
      ...context,
      testCases: normalizedTestCases,
      testCaseCount: normalizedTestCases.length,
      skippedCount: skipped.length,
      skipped,
    },
  },
];

